    fn job_shop_schedule_feasible(
        &self,
        jobs: &[JobShopJob],
        schedule: &[ScheduledOperation],
    ) -> bool {
        let total_ops: usize = jobs.iter().map(|job| job.operations.len()).sum();
        if schedule.len() != total_ops {
            return false;
        }

        let mut seen: HashSet<(String, usize)> = HashSet::new();
        for op in schedule {
            if op.start < -1e-9 || op.finish + 1e-9 < op.start {
                return false;
            }
            if !seen.insert((op.job_id.clone(), op.op_index)) {
                return false;
            }
            let Some(job) = jobs.iter().find(|job| job.id == op.job_id) else {
                return false;
            };
            let Some(expected) = job.operations.get(op.op_index) else {
                return false;
            };
            if expected.machine != op.machine {
                return false;
            }
            if ((op.finish - op.start) - expected.duration).abs()
                > 1e-8 * 1.0_f64.max(expected.duration.abs())
            {
                return false;
            }
            if op.op_index > 0 {
                let Some(previous) = schedule
                    .iter()
                    .find(|other| other.job_id == op.job_id && other.op_index == op.op_index - 1)
                else {
                    return false;
                };
                if previous.finish > op.start + 1e-9 {
                    return false;
                }
            }
        }

        for job in jobs {
            for op_index in 0..job.operations.len() {
                if !seen.contains(&(job.id.clone(), op_index)) {
                    return false;
                }
            }
        }

        for i in 0..schedule.len() {
            for j in (i + 1)..schedule.len() {
                let a = &schedule[i];
                let b = &schedule[j];
                if a.machine == b.machine && a.start.max(b.start) < a.finish.min(b.finish) - 1e-9 {
                    return false;
                }
            }
        }
        true
    }

    fn flow_shop_schedule_feasible(
        &self,
        jobs: &[FlowShopJob],
        schedule: &[ScheduledOperation],
        sequence: &[String],
    ) -> bool {
        let Some(first) = jobs.first() else {
            return schedule.is_empty() && sequence.is_empty();
        };
        let machine_count = first.processing_times.len();
        if machine_count == 0
            || jobs
                .iter()
                .any(|job| job.processing_times.len() != machine_count)
            || sequence.len() != jobs.len()
            || schedule.len() != jobs.len() * machine_count
        {
            return false;
        }

        let mut seen_jobs = HashSet::new();
        for job_id in sequence {
            if !seen_jobs.insert(job_id.clone())
                || !jobs.iter().any(|job| job.id.as_str() == job_id.as_str())
            {
                return false;
            }
        }

        let mut machine_ready = vec![0.0_f64; machine_count];
        for (position, job_id) in sequence.iter().enumerate() {
            let Some(job) = jobs.iter().find(|job| job.id.as_str() == job_id.as_str()) else {
                return false;
            };
            let mut job_ready = 0.0_f64;
            for machine_index in 0..machine_count {
                let op = &schedule[position * machine_count + machine_index];
                let duration = job.processing_times[machine_index];
                let expected_machine = format!("M{}", machine_index + 1);
                let earliest_start = machine_ready[machine_index].max(job_ready);
                if op.job_id.as_str() != job_id.as_str()
                    || op.op_index != machine_index
                    || op.machine != expected_machine
                    || op.start < -1e-9
                    || op.finish + 1e-9 < op.start
                    || op.start + 1e-9 < earliest_start
                    || ((op.finish - op.start) - duration).abs()
                        > 1e-8 * 1.0_f64.max(duration.abs())
                {
                    return false;
                }
                machine_ready[machine_index] = op.finish;
                job_ready = op.finish;
            }
        }
        true
    }

    fn bin_packing_external_bins_feasible(
        &self,
        problem: &BinPackingProblem,
        bins: &[ExternalBinPackingReferenceBin],
    ) -> bool {
        if bins.is_empty() {
            return problem.items.is_empty();
        }
        let mut seen = HashSet::new();
        for bin in bins {
            if bin.load > problem.capacity + 1e-8 {
                return false;
            }
            let mut load = 0.0;
            for item_id in &bin.item_ids {
                if !seen.insert(item_id.clone()) {
                    return false;
                }
                let Some(item) = problem
                    .items
                    .iter()
                    .find(|item| item.id.as_str() == item_id.as_str())
                else {
                    return false;
                };
                load += item.weight;
            }
            if (load - bin.load).abs() > 1e-8 * 1.0_f64.max(load.abs()) {
                return false;
            }
        }
        seen.len() == problem.items.len()
    }

