                    && (report.internal.x[open_a] - 1.0).abs() <= 1e-7
                    && report.internal.x[open_b].abs() <= 1e-7
                    && (report.internal.x[load] - 4.0).abs() <= 1e-7
                    && report.internal.x[reserve].abs() <= 1e-7
