    fn validate_minimum_spanning_tree(&mut self) {
        println!(
            "\n-- Minimum spanning tree: Kruskal/Prim vs Rust reference / OR-Tools CP-SAT bridge --"
        );
        let problem = build_sample_minimum_spanning_tree_problem();
        let kruskal = solve_minimum_spanning_tree_kruskal(&problem);
        let prim = solve_minimum_spanning_tree_prim(&problem);
        self.check(
            "MST Kruskal native optimum",
            kruskal.status == MinimumSpanningTreeStatus::Optimal
                && kruskal.total_weight == Some(6.0)
                && minimum_spanning_tree_solution_feasible(&problem, &kruskal),
            format!(
                "status={} weight={:?} edges={:?}",
                kruskal.status.as_str(),
                kruskal.total_weight,
                kruskal.selected_edge_ids
            ),
        );
        self.check(
            "MST Prim native matches Kruskal",
            prim.status == MinimumSpanningTreeStatus::Optimal
                && prim.total_weight == kruskal.total_weight
                && minimum_spanning_tree_solution_feasible(&problem, &prim),
            format!(
                "status={} weight={:?} edges={:?}",
                prim.status.as_str(),
                prim.total_weight,
                prim.selected_edge_ids
            ),
        );

        let reference = solve_minimum_spanning_tree_with_external_reference(
            &problem,
            &ExternalMinimumSpanningTreeReferenceOptions {
                solver: ExternalMinimumSpanningTreeReferenceSolver::RustKruskal,
            },
        );
        self.check(
            "MST exact/reference bridge status optimal",
            reference.status == ExternalMinimumSpanningTreeReferenceStatus::Optimal,
            format!(
                "status={} solver={} message={}",
                reference.status.as_str(),
                reference.solver,
                reference.message
            ),
        );
        self.close(
            "MST exact/reference objective",
            kruskal.total_weight.unwrap_or(f64::NAN),
            reference.objective.unwrap_or(f64::NAN),
            0.0,
        );
        self.check(
            "MST exact/reference feasibility",
            self.minimum_spanning_tree_external_solution_feasible(
                &problem,
                &reference.selected_edge_indices,
                &reference.selected_edge_ids,
                reference.total_weight,
            ),
            format!(
                "objective={:?} edges={:?}",
                reference.objective, reference.selected_edge_ids
            ),
        );

        match (
            reference.ortools_status.as_deref(),
            reference.ortools_objective,
        ) {
            (Some("optimal"), Some(objective)) => {
                self.close(
                    "MST OR-Tools CP-SAT objective",
                    kruskal.total_weight.unwrap_or(f64::NAN),
                    objective,
                    0.0,
                );
                self.check(
                    "MST OR-Tools CP-SAT feasibility",
                    self.minimum_spanning_tree_external_solution_feasible(
                        &problem,
                        &reference.ortools_selected_edge_indices,
                        &reference.ortools_selected_edge_ids,
                        reference.ortools_total_weight,
                    ),
                    format!(
                        "objective={:?} edges={:?} bound={:?}",
                        reference.ortools_objective,
                        reference.ortools_selected_edge_ids,
                        reference.ortools_objective_bound
                    ),
                );
            }
            _ => println!(
                "  SKIP  MST OR-Tools CP-SAT objective: no OR-Tools sidecar in solver={} message={}",
                reference.solver, reference.message
            ),
        }
    }

    fn validate_traveling_salesman(&mut self) {
        println!("\n-- TSP: native Held-Karp/ACO vs Rust reference / OR-Tools Routing bridge --");
        let instance = build_pentagon_tsp(6, 10.0);
        let exact = held_karp_exact(&instance);
        self.check(
            "TSP Held-Karp native tour feasibility",
            is_permutation(&exact.tour, instance.n),
            format!("tour={:?} length={:.10}", exact.tour, exact.length),
        );
        self.close(
            "TSP Held-Karp native length self-check",
            exact.length,
            tour_length(&instance, &exact.tour),
            1e-9,
        );

        let aco_points = instance
            .coordinates
            .iter()
            .map(|&(x, y)| Point2 { x, y })
            .collect::<Vec<_>>();
        let aco = run_ant_colony_tsp(AntColonyTSPParams {
            points: Some(aco_points),
            ants: Some(36),
            iterations: Some(120),
            seed: Some(17),
            ..Default::default()
        });
        let mut aco_tour = aco.best_tour.clone();
        let aco_closed = aco_tour.len() == instance.n + 1
            && aco_tour
                .first()
                .zip(aco_tour.last())
                .is_some_and(|(a, b)| a == b);
        if aco_closed {
            aco_tour.pop();
        }
        let aco_permutation = is_permutation(&aco_tour, instance.n);
        self.check(
            "TSP ant-colony closed-tour feasibility",
            aco_closed && aco_permutation,
            format!(
                "raw_tour={:?} normalized_tour={:?} length={:.10}",
                aco.best_tour, aco_tour, aco.best_length
            ),
        );
        if aco_permutation {
            self.close(
                "TSP ant-colony reported length",
                aco.best_length,
                tour_length(&instance, &aco_tour),
                1e-8,
            );
            self.check(
                "TSP ant-colony bounded by Held-Karp",
                aco.best_length + 1e-8 >= exact.length,
                format!("exact={:.10} aco={:.10}", exact.length, aco.best_length),
            );
        } else {
            self.check(
                "TSP ant-colony reported length",
                false,
                format!("invalid normalized_tour={aco_tour:?}"),
            );
        }

        let reference = solve_tsp_with_external_reference(
            &instance.distance,
            &ExternalTspReferenceOptions {
                solver: ExternalTspReferenceSolver::RustHeldKarp,
            },
        );
        self.check(
            "TSP external-reference bridge status optimal",
            reference.status == ExternalTspReferenceStatus::Optimal,
            format!(
                "status={} solver={} message={}",
                reference.status.as_str(),
                reference.solver,
                reference.message
            ),
        );
        self.close(
            "TSP external-reference objective",
            exact.length,
            reference.objective.unwrap_or(f64::NAN),
            1e-8,
        );
        let reference_permutation = is_permutation(&reference.tour, instance.n);
        self.check(
            "TSP external-reference tour feasibility",
            reference_permutation,
            format!("tour={:?}", reference.tour),
        );
        if reference_permutation {
            self.close(
                "TSP external-reference tour length",
                exact.length,
                tour_length(&instance, &reference.tour),
                1e-8,
            );
        }
        match (
            reference.ortools_status.as_deref(),
            reference.ortools_objective,
        ) {
            (Some("optimal"), Some(objective)) => {
                self.close(
                    "TSP OR-Tools Routing objective",
                    exact.length,
                    objective,
                    1e-6,
                );
                self.check(
                    "TSP OR-Tools Routing tour feasibility",
                    is_permutation(&reference.ortools_tour, instance.n),
                    format!("tour={:?}", reference.ortools_tour),
                );
            }
            _ => println!(
                "  SKIP  TSP OR-Tools Routing objective: no OR-Tools sidecar in solver={} message={}",
                reference.solver, reference.message
            ),
        }
    }

    fn validate_vehicle_routing(&mut self) {
        println!("\n-- Vehicle routing: exact CVRP vs OR-Tools Routing bridge --");
        let customers = vec![
            VRPCustomer {
                id: "A".to_string(),
                x: 1.0,
                y: 2.0,
                demand: 2.0,
            },
            VRPCustomer {
                id: "B".to_string(),
                x: 2.0,
                y: 1.0,
                demand: 2.0,
            },
            VRPCustomer {
                id: "C".to_string(),
                x: 4.0,
                y: 1.0,
                demand: 2.0,
            },
            VRPCustomer {
                id: "D".to_string(),
                x: 5.0,
                y: 2.0,
                demand: 1.0,
            },
            VRPCustomer {
                id: "E".to_string(),
                x: 3.0,
                y: 4.0,
                demand: 2.0,
            },
        ];
        let params = VRPSavingsParams {
            depot: Some(Point { x: 0.0, y: 0.0 }),
            customers: Some(customers.clone()),
            vehicle_capacity: Some(5.0),
        };
        let exact = run_vrp_exact(params.clone());
        let savings = run_vrp_savings(params.clone());
        let nearest = run_vrp_nearest_neighbor(params.clone());
        let served: usize = exact.routes.iter().map(|route| route.customers.len()).sum();
        self.check(
            "CVRP exact native feasibility",
            served == customers.len() && exact.routes.iter().all(|route| route.load <= 5.0 + 1e-9),
            format!(
                "routes={:?} total={:.10}",
                exact.routes, exact.total_distance
            ),
        );
        self.check(
            "CVRP heuristics bounded by exact optimum",
            savings.total_distance + 1e-9 >= exact.total_distance
                && nearest.total_distance + 1e-9 >= exact.total_distance,
            format!(
                "exact={:.10} savings={:.10} nearest={:.10}",
                exact.total_distance, savings.total_distance, nearest.total_distance
            ),
        );

        let reference = solve_cvrp_with_external_reference(
            Point { x: 0.0, y: 0.0 },
            &customers,
            5.0,
            &ExternalRoutingReferenceOptions::default(),
        );
        self.check(
            "CVRP exact/reference status",
            reference.status == ExternalRoutingReferenceStatus::Optimal,
            format!(
                "status={} solver={} message={} route_masks={:?}",
                reference.status.as_str(),
                reference.solver,
                reference.message,
                reference.feasible_route_masks
            ),
        );
        self.close(
            "CVRP exact/reference objective",
            exact.total_distance,
            reference.objective.unwrap_or(f64::NAN),
            1e-8,
        );
        self.check(
            "CVRP exact/reference route feasibility",
            reference
                .routes
                .iter()
                .all(|route| route.load <= 5.0 + 1e-9)
                && reference
                    .routes
                    .iter()
                    .map(|route| route.customers.len())
                    .sum::<usize>()
                    == customers.len()
                && reference.routes.iter().all(|route| route.distance >= 0.0),
            format!("routes={:?}", reference.routes),
        );
        match (
            reference.ortools_status.as_deref(),
            reference.ortools_objective,
        ) {
            (Some("optimal"), Some(objective)) => self.close(
                "CVRP OR-Tools Routing objective",
                exact.total_distance,
                objective,
                1e-6,
            ),
            _ => println!(
                "  SKIP  CVRP OR-Tools Routing objective: status={:?} message={:?}",
                reference.ortools_status, reference.ortools_message
            ),
        }
    }

    fn validate_job_shop_scheduling(&mut self) {
        println!("\n-- Scheduling: exact job-shop vs OR-Tools CP-SAT bridge --");
        let jobs = self.sample_job_shop_jobs();
        let params = JobShopDispatchParams {
            jobs: Some(jobs.clone()),
            rule: Some(DispatchRule::Spt),
        };
        let exact = run_job_shop_exact(params.clone());
        let dispatch = run_job_shop_dispatch(params);
        self.check(
            "Job-shop exact native feasibility",
            self.job_shop_schedule_feasible(&jobs, &exact.schedule),
            format!(
                "operations={} makespan={:.10} total_flow={:.10}",
                exact.schedule.len(),
                exact.makespan,
                exact.total_flow_time
            ),
        );
        self.check(
            "Job-shop exact improves/bounds dispatch",
            exact.makespan <= dispatch.makespan + 1e-9,
            format!(
                "exact={:.10} dispatch={:.10}",
                exact.makespan, dispatch.makespan
            ),
        );
        self.close("Job-shop exact known optimum", exact.makespan, 9.0, 1e-10);

        let external = solve_job_shop_with_external_reference(
            &jobs,
            &ExternalSchedulingReferenceOptions::default(),
        );
        self.check(
            "Job-shop exact/reference bridge status optimal",
            external.status == ExternalSchedulingReferenceStatus::Optimal,
            format!(
                "status={} solver={} message={}",
                external.status.as_str(),
                external.solver,
                external.message
            ),
        );
        self.close(
            "Job-shop exact/reference makespan",
            exact.makespan,
            external.makespan.unwrap_or(f64::NAN),
            1e-8,
        );
        self.close(
            "Job-shop exact/reference total flow",
            exact.total_flow_time,
            external.total_flow_time.unwrap_or(f64::NAN),
            1e-8,
        );
        self.check(
            "Job-shop exact/reference feasibility",
            self.job_shop_schedule_feasible(&jobs, &external.schedule),
            format!(
                "external_ops={} external_makespan={:?}",
                external.schedule.len(),
                external.makespan
            ),
        );

        match (
            external.ortools_status.as_deref(),
            external.ortools_makespan,
        ) {
            (Some("optimal"), Some(makespan)) => {
                self.close(
                    "Job-shop OR-Tools CP-SAT makespan",
                    exact.makespan,
                    makespan,
                    1e-8,
                );
                self.check(
                    "Job-shop OR-Tools CP-SAT feasibility",
                    self.job_shop_schedule_feasible(&jobs, &external.ortools_schedule),
                    format!(
                        "ortools_ops={} ortools_total_flow={:?}",
                        external.ortools_schedule.len(),
                        external.ortools_total_flow_time
                    ),
                );
            }
            _ => println!(
                "  SKIP  Job-shop OR-Tools CP-SAT makespan: status={:?} message={}",
                external.ortools_status, external.message
            ),
        }
    }

